export function validateBody(fields) {
  return (req, res, next) => {
    for (const field of fields) {
      if (!req.body || req.body[field] === undefined) {
        return res.status(400).json({ error: `Missing field: ${field}` });
      }
    }
    next();
  };
}

export function parseQuery(req, res, next) {
  const { page, limit } = req.query;
  req.pagination = {
    page: Number(page) || 1,
    limit: Number(limit) || 10,
  };
  next();
}

export function formatResponse(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = (data) => {
    if (res.statusCode >= 400) {
      return originalJson(data);
    }
    return originalJson({ success: true, data });
  };
  next();
}

import express from 'express';
import { validateBody } from './middleware/validate-body.js';
import { parseQuery } from './middleware/parse-query.js';
import { formatResponse } from './middleware/format-response.js';

const app = express();

app.use(express.json());
app.use(formatResponse);
app.use(parseQuery);

const items = [
  { id: 1, name: 'Widget', price: 9.99 },
  { id: 2, name: 'Gadget', price: 14.99 },
  { id: 3, name: 'Gizmo', price: 4.99 },
  { id: 4, name: 'Thingamajig', price: 19.99 },
  { id: 5, name: 'Doohickey', price: 7.99 },
];

app.get('/api/items', (req, res) => {
  const { page, limit } = req.pagination;
  const start = (page - 1) * limit;
  const paged = items.slice(start, start + limit);
  res.json(paged);
});

app.post('/api/items', validateBody(['name', 'price']), (req, res) => {
  const item = { id: items.length + 1, ...req.body };
  items.push(item);
  res.status(201).json(item);
});

export default app;

import app from './app.js';

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
